      case ApronFarmerBodyColor.green:
        switch (pose) {
          case ApronFarmerBodyPose.turnip:
            svgString = _farmerBodyGreenTurnip;
          case ApronFarmerBodyPose.tomato:
            svgString = _farmerBodyGreenTomato;
        }
    }
    return SvgPicture.string(
      svgString,
      height: height,
      width: width,
      colorMapper: colorMapper,
    );
  }
}
